def validate_agent_message(value):
    """Validate Hive agent message envelope structure."""

    # Check if value is a dict
    if not isinstance(value, dict):
        return ('INVALID_INPUT_TYPE',)

    errors = []

    # Required non-empty trimmed strings
    required_fields = ['agent_id', 'agent_type', 'task_id', 'status', 'audience', 'trust_class', 'message']

    for field in required_fields:
        if field not in value:
            errors.append(f'MISSING_{field.upper()}')
        elif not isinstance(value[field], str):
            errors.append(f'INVALID_TYPE_{field}')
        else:
            trimmed = value[field].strip()
            if not trimmed:
                errors.append(f'EMPTY_{field}')

    # agent_type validation
    valid_agent_types = ['model', 'human']
    if 'agent_type' in value and value['agent_type'].lower() not in valid_agent_types:
        errors.append('INVALID_AGENT_TYPE')

    # status validation
    valid_statuses = ['DONE', 'NEEDS_USER', 'BLOCKED']
    if 'status' in value and value['status'].upper() not in valid_statuses:
        errors.append('INVALID_STATUS')

    # audience validation - must be 'mind'
    if 'audience' in value and value['audience'].lower() != 'mind':
        errors.append('INVALID_AUDIENCE')

    # trust_class validation - must match agent_type
    valid_trust_classes = {
        'model': ['unverified_model_output'],
        'human': ['human_agent_statement']
    }

    if 'trust_class' in value and 'agent_type' not in value:
        errors.append('MISSING_AGENT_TYPE')
    elif 'trust_class' in value and 'agent_type' in value:
        agent_type = value['agent_type'].lower()
        trust_class = value['trust_class'].lower() if isinstance(value['trust_class'], str) else ''

        expected_trust_classes = valid_trust_classes.get(agent_type, [])
        if trust_class not in expected_trust_classes:
            errors.append('INVALID_TRUST_CLASS')

    # artifact_refs must be a list of strings
    if 'artifact_refs' in value and not isinstance(value['artifact_refs'], list):
        errors.append('ARTIFACT_REFS_NOT_LIST')
    elif 'artifact_refs' in value and len(value['artifact_refs']) > 0:
        for item in value['artifact_refs']:
            if not isinstance(item, str):
                errors.append('INVALID_ARTIFACT_REF_ITEM')

    # uncertainties must be a list of strings
    if 'uncertainties' in value and not isinstance(value['uncertainties'], list):
        errors.append('UNCERTAINTIES_NOT_LIST')

    # conflicts_with must be a list of strings
    if 'conflicts_with' in value and not isinstance(value['conflicts_with'], list):
        errors.append('CONFLICTS_WITH_NOT_LIST')

    # claims validation - must be a list
    if 'claims' not in value:
        errors.append('MISSING_CLAIMS')
    elif not isinstance(value['claims'], list):
        errors.append('CLAIMS_NOT_LIST')
    else:
        for i, claim in enumerate(value['claims']):
            # Each item must be a dict
            if not isinstance(claim, dict):
                errors.append(f'INVALID_CLAIM_ITEM_{i}')
                continue

            # text field - required non-empty string
            if 'text' not in claim:
                errors.append(f'MISSING_TEXT_IN_CLAIM_{i}')
            elif not isinstance(claim['text'], str) or not claim['text'].strip():
                errors.append(f'INVALID_TEXT_IN_CLAIM_{i}')

            # evidence_ids - must be a list of strings
            if 'evidence_ids' in claim and not isinstance(claim['evidence_ids'], list):
                errors.append(f'EVIDENCE_IDS_NOT_LIST_IN_CLAIM_{i}')

            # kind - must be one of the valid kinds
            valid_kinds = ['retrieved_fact', 'inference', 'proposal']
            if 'kind' in claim and claim['kind'].lower() not in valid_kinds:
                errors.append(f'INVALID_KIND_IN_CLAIM_{i}')

    # parent_task_id validation - may be absent or null, otherwise must be non-empty string
    if 'parent_task_id' in value:
        if value['parent_task_id'] is None:
            pass  # Valid
        elif not isinstance(value['parent_task_id'], str):
            errors.append('INVALID_PARENT_TASK_ID_TYPE')
        else:
            trimmed = value['parent_task_id'].strip()
            if not trimmed:
                errors.append('EMPTY_PARENT_TASK_ID')

    return tuple(errors)
